// LuaJIT script runtime: one VM per logical side, one environment per mod, API parity with the C ABI.
#pragma once
#include "common.h"

struct lua_State;

namespace kyubu {

struct Mod;

// Puts <dir>/?.lua first in package.path, so full-trust mods can require the modules shipped there
// (kyubu/lua/: require("cubeworld"), generated by kmap export).
void add_module_dir(lua_State* L, const std::string& dir);

class LuaRuntime {
public:
    static LuaRuntime& get();

    // Loads every mod's scripts for the sides present in this host (PreInit).
    void load_all();
    // Unloads and re-runs one mod's scripts (dev mode). Returns a status line.
    std::string reload(Mod* mod);
    // Runs code in a side's VM with full trust (console). Returns printed output / result.
    std::string eval(KyubuSide side, const std::string& code);
    // Checks script files of folder mods for changes (dev mode) and reloads changed mods.
    void poll_changes();
    void shutdown();

    size_t memory_kb(KyubuSide side);
    bool has_vm(KyubuSide side);
};

}  // namespace kyubu
